using System.Data;using System.Data.Common;using Microsoft.EntityFrameworkCore;using TCT.LMS.Application.Interfaces.Repositories;using TCT.LMS.Data.Common;
namespace TCT.LMS.Infrastructure.Repositories;
public sealed class CoordinatorAdminDashboardRepository:ICoordinatorAdminDashboardRepository
{
 private readonly ApplicationDbContext _db;public CoordinatorAdminDashboardRepository(ApplicationDbContext db)=>_db=db;
 public Task<IReadOnlyList<IReadOnlyDictionary<string,object?>>> QueryAsync(CoordinatorAdminDashboardQuery q,DateTime f,DateTime t,int take,CancellationToken token)=>Run(Sql(q),f,t,take,token);
 private static string Sql(CoordinatorAdminDashboardQuery q)=>q switch{
 CoordinatorAdminDashboardQuery.Summary=>@"SELECT COUNT(DISTINCT sd.Coordinator) Coordinators,COUNT(DISTINCT sd.Id) TotalInflow,COUNT(DISTINCT s.StudentId) Students,SUM(CASE WHEN tc.TypeCodeValue=20012 THEN CONVERT(bigint,1) ELSE 0 END) PendingApprovals,COUNT(DISTINCT CASE WHEN sch.ScheduleId IS NOT NULL THEN sd.Id END) Converted,CAST(100.0*COUNT(DISTINCT CASE WHEN sch.ScheduleId IS NOT NULL THEN sd.Id END)/NULLIF(COUNT(DISTINCT sd.Id),0) AS decimal(5,2)) ConversionRate FROM dbo.SalesDetails sd JOIN dbo.Sales s ON s.Id=sd.SalesId LEFT JOIN dbo.Type_Code tc ON tc.Id=sd.Status LEFT JOIN dbo.Schedule sch ON sch.StudentId=s.StudentId AND sch.SalesDetailsId=sd.Id AND sch.IsActive=1 WHERE sd.IsActive=1 AND s.IsActive=1 AND s.CreatedDate>=@FromDate AND s.CreatedDate<DATEADD(day,1,@ToDate);",
 CoordinatorAdminDashboardQuery.Coordinators=>@"SELECT TOP (@Take) sd.Coordinator CoordinatorId,COALESCE(u.FullName,CONCAT(u.FirstName,N' ',u.LastName)) CoordinatorName,COUNT(DISTINCT sd.Id) Inflow,COUNT(DISTINCT s.StudentId) Students,SUM(CASE WHEN tc.TypeCodeValue=20012 THEN CONVERT(bigint,1) ELSE 0 END) PendingApprovals,COUNT(DISTINCT CASE WHEN sch.ScheduleId IS NOT NULL THEN sd.Id END) Converted,CAST(100.0*COUNT(DISTINCT CASE WHEN sch.ScheduleId IS NOT NULL THEN sd.Id END)/NULLIF(COUNT(DISTINCT sd.Id),0) AS decimal(5,2)) SuccessRate FROM dbo.SalesDetails sd JOIN dbo.Sales s ON s.Id=sd.SalesId JOIN dbo.[User] u ON u.Id=sd.Coordinator LEFT JOIN dbo.Type_Code tc ON tc.Id=sd.Status LEFT JOIN dbo.Schedule sch ON sch.StudentId=s.StudentId AND sch.SalesDetailsId=sd.Id AND sch.IsActive=1 WHERE sd.IsActive=1 AND s.IsActive=1 AND s.CreatedDate>=@FromDate AND s.CreatedDate<DATEADD(day,1,@ToDate) GROUP BY sd.Coordinator,u.FullName,u.FirstName,u.LastName ORDER BY SuccessRate DESC;",
 CoordinatorAdminDashboardQuery.PendingApprovals=>@"SELECT TOP (@Take) sd.Id SalesDetailsId,sd.Coordinator CoordinatorId,COALESCE(c.FullName,CONCAT(c.FirstName,N' ',c.LastName)) CoordinatorName,COALESCE(stu.FullName,CONCAT(stu.FirstName,N' ',stu.LastName)) StudentName,COALESCE(tu.FullName,CONCAT(tu.FirstName,N' ',tu.LastName)) TutorName,sub.TypeCodeName SubjectName,tc.TypeCodeName StatusName,sd.ModifiedDate FROM dbo.SalesDetails sd JOIN dbo.Sales s ON s.Id=sd.SalesId JOIN dbo.Student st ON st.Id=s.StudentId JOIN dbo.[User] stu ON stu.Id=st.UserId JOIN dbo.[User] c ON c.Id=sd.Coordinator LEFT JOIN dbo.[User] tu ON tu.Id=sd.TutorId LEFT JOIN dbo.Type_Code sub ON sub.Id=sd.SubjectId LEFT JOIN dbo.Type_Code tc ON tc.Id=sd.Status WHERE sd.IsActive=1 AND s.IsActive=1 AND tc.TypeCodeValue=20012 ORDER BY sd.ModifiedDate;",
 CoordinatorAdminDashboardQuery.DemoPipeline=>@"SELECT tc.TypeCodeName StatusName,COUNT_BIG(*) DemoCount FROM dbo.SalesDetails sd JOIN dbo.Sales s ON s.Id=sd.SalesId LEFT JOIN dbo.Type_Code tc ON tc.Id=sd.Status WHERE sd.IsActive=1 AND s.IsActive=1 AND s.CreatedDate>=@FromDate AND s.CreatedDate<DATEADD(day,1,@ToDate) GROUP BY tc.TypeCodeName ORDER BY DemoCount DESC;",_=>throw new ArgumentOutOfRangeException(nameof(q),q,null)};
 private async Task<IReadOnlyList<IReadOnlyDictionary<string,object?>>> Run(string sql,DateTime f,DateTime t,int take,CancellationToken token){DbConnection c=_db.Database.GetDbConnection();var opened=c.State!=ConnectionState.Open;if(opened)await c.OpenAsync(token);try{await using var cmd=c.CreateCommand();cmd.CommandText=sql;if(sql.Contains("@FromDate"))Add(cmd,"@FromDate",DbType.Date,f);if(sql.Contains("@ToDate"))Add(cmd,"@ToDate",DbType.Date,t);if(sql.Contains("@Take"))Add(cmd,"@Take",DbType.Int32,take);var rows=new List<IReadOnlyDictionary<string,object?>>();await using var r=await cmd.ExecuteReaderAsync(token);while(await r.ReadAsync(token)){var row=new Dictionary<string,object?>(r.FieldCount,StringComparer.OrdinalIgnoreCase);for(int i=0;i<r.FieldCount;i++)row[r.GetName(i)]=await r.IsDBNullAsync(i,token)?null:r.GetValue(i);rows.Add(row);}return rows;}finally{if(opened)await c.CloseAsync();}}
 private static void Add(DbCommand c,string n,DbType t,object v){var p=c.CreateParameter();p.ParameterName=n;p.DbType=t;p.Value=v;c.Parameters.Add(p);}
}

